```python
import json

# A literal is (predicate, subject, object, polarity).
def lit(predicate, subject, obj="", positive=True):
    return (predicate, subject, obj, positive)

facts = {
    lit("negotiates", "ant", "stork"),
    lit("photographs", "dragon", "fish"),
    lit("hides_cards_from", "mannikin", "liger"),
    lit("located_in", "mouse", "Nigeria"),
    lit("neglects", "worm", "chihuahua"),
    lit("surrenders_to", "crow", "wolf", False),
    lit("trades_piece_with", "dalmatian", "stork", False),
}
money = {"stork": 98}
animals = {
    "ant", "stork", "dragon", "fish", "mannikin", "liger", "mouse",
    "worm", "chihuahua", "crow", "wolf", "dalmatian", "goat",
    "walrus", "beetle", "cobra", "dinosaur", "llama", "husky",
}

rules = []

def rule(name, premises, conclusion):
    rules.append((name, frozenset(premises), conclusion))

rule("Nigeria_in_Africa", [lit("located_in", "mouse", "Nigeria")],
     lit("located_in", "mouse", "Africa"))

# A comparison is established only when both amounts are known.
if "stork" in money and "walrus" in money:
    if money["stork"] > money["walrus"]:
        facts.add(lit("richer_than", "stork", "walrus"))

rule("Rule1", [
    lit("negotiates", "ant", "stork"),
    lit("trades_piece_with", "dalmatian", "stork", False),
], lit("builds_plant", "stork", "goat_fields"))

for animal in sorted(animals):
    rule("plant_witness:" + animal,
         [lit("builds_plant", animal, "goat_fields")],
         lit("exists_plant_builder", "", "goat_fields"))
    rule("photo_witness:" + animal,
         [lit("photographs", animal, "fish")],
         lit("exists_photographer", "", "fish"))
    rule("Rule5:" + animal, [
        lit("hugs", animal, "dinosaur"),
        lit("smiles_at", animal, "cobra"),
    ], lit("shouts_at", animal, "beetle"))

rule("Rule2", [lit("exists_plant_builder", "", "goat_fields")],
     lit("shouts_at", "mouse", "beetle", False))
rule("Rule3", [lit("richer_than", "stork", "walrus")],
     lit("builds_plant", "stork", "goat_fields", False))
rule("Rule4", [lit("located_in", "mouse", "Africa")],
     lit("smiles_at", "mouse", "cobra"))
rule("Rule6", [lit("has_instrument", "llama")],
     lit("calls", "llama", "husky"))
rule("Rule7", [lit("works_in_agriculture", "mouse")],
     lit("smiles_at", "mouse", "cobra", False))
rule("Rule8", [lit("exists_photographer", "", "fish")],
     lit("calls", "llama", "husky", False))

preferences = {
    ("Rule3", "Rule1"), ("Rule5", "Rule2"),
    ("Rule6", "Rule8"), ("Rule7", "Rule4"),
}

def opposite(x):
    return x[:3] + (not x[3],)

def family(name):
    return name.split(":")[0]

known = set(facts)
support = {x: "given" for x in facts}
seen = set()

while True:
    state = frozenset(known)
    if state in seen:
        print(json.dumps({"final_answer": "UNSUPPORTED",
                          "evidence": "Inference did not stabilize."}))
        break
    seen.add(state)

    eligible = [r for r in rules if r[1] <= known]
    additions = {}
    for name, premises, conclusion in eligible:
        opponents = [
            r for r in eligible if r[2] == opposite(conclusion)
        ]
        if all((family(name), family(r[0])) in preferences
               for r in opponents):
            additions.setdefault(conclusion, name)

    updated = facts | set(additions)
    if updated == known:
        support.update(additions)
        positive = lit("shouts_at", "mouse", "beetle")
        negative = opposite(positive)
        p, n = positive in known, negative in known

        if p and n:
            answer = "UNSUPPORTED"
        elif p:
            answer = "proved"
        elif n:
            answer = "disproved"
        else:
            answer = "unknown"

        print(json.dumps({
            "final_answer": answer,
            "evidence": {
                "mouse_shouts": p,
                "mouse_does_not_shout": n,
                "negative_support": support.get(negative),
                "plant_support": support.get(
                    lit("builds_plant", "stork", "goat_fields")
                ),
                "Rule3_antecedent_established":
                    lit("richer_than", "stork", "walrus") in known,
                "Rule5_mouse_hug_established":
                    lit("hugs", "mouse", "dinosaur") in known,
            },
        }, separators=(",", ":")))
        break

    known = updated
    support.update(additions)
